 update(dt,input,world){if(world.driving){if(input.actions&4){const v=world.driving;world.driving=null;v.driver=null;this.x=v.x+Math.cos(v.angle)*34;this.y=v.y+Math.sin(v.angle)*34;return;}const v=world.driving;v.update(dt,{throttle:(input.down('KeyW')?1:0)-(input.down('KeyS')?1:0),steer:(input.down('KeyD')?1:0)-(input.down('KeyA')?1:0),handbrake:input.down('Space')},world);return;}const dx=(input.down('KeyD')||input.down('ArrowRight')?1:0)-(input.down('KeyA')||input.down('ArrowLeft')?1:0),dy=(input.down('KeyS')||input.down('ArrowDown')?1:0)-(input.down('KeyW')||input.down('ArrowUp')?1:0),m=Math.hypot(dx,dy)||1;this.speed=input.down('ShiftLeft')||input.down('ShiftRight')?300:170;this.vx=dx/m*this.speed;this.vy=dy/m*this.speed;if(dx||dy)this.angle=Math.atan2(dx,-dy);const nx=this.x+this.vx*dt,ny=this.y+this.vy*dt;if(world.city.isLand(nx,ny)&&!world.city.collidesBuilding(nx,ny,8)){this.x=nx;this.y=ny;}if(input.actions&4){const car=world.nearestCar(this.x,this.y,55);if(car){world.driving=car;car.driver='player';}}}
 draw(c,cam,world){if(world.driving)return; c.save();c.translate(this.x,this.y);c.fillStyle='rgba(25,28,25,.25)';c.beginPath();c.ellipse(2,5,9,5,0,0,7);c.fill();c.fillStyle='#cf694f';c.beginPath();c.arc(0,0,7,0,7);c.fill();c.fillStyle='#e8bd91';c.beginPath();c.arc(0,-7,4,0,7);c.fill();c.rotate(this.angle);c.fillStyle='#f7e8c8';c.fillRect(-1,-14,2,5);c.restore();if(world.nearestCar(this.x,this.y,55)){c.fillStyle='#fff2c9';c.font='bold 16px sans-serif';c.fillText('E',this.x+12,this.y-15);}}
}
